export const BODY: string = "\n<p>السطوع أبسط إصلاح للصور وأول ما يلجأ إليه الناس: صورة داكنة تصبح مرئية، وصورة مغسولة تكتسب عمقًا، ولقطة باهتة تعود إلى الحياة.</p>\n<p>لكن السطوع سهل المبالغة فيه: إذا دفعته أكثر مما يلزم، تصبح الصورة مسطحة ورمادية، مع إضاءات محروقة ولا تفاصيل في المناطق الفاتحة.</p>\n<p>يشرح هذا الدليل كيف يعمل السطوع وكيف تستخدم المنزلق والإعدادات السريعة جيدًا وكيف تصلح صورًا داكنة دون إتلافها: يغطي صورًا شخصية ومناظر ولقطات شاشة وأخطاء تفسد صورة جيدة.</p>\n<h2 id=\"what-brightness-does\">ماذا يفعل السطوع فعلًا؟</h2>\n<p>ينقل السطوع كل بكسل في الصورة نحو الأبيض أو نحو الأسود: عند رفعه، تفتّح المناطق الداكنة وتفتّح الفاتحة أكثر، وعند خفضه يظلم كل شيء.</p>\n<p>التغيير موحد في الصورة كلها: تعديل سطوع لا يختار الظلال ولا الإضاءات، بل يحرك النطاق النغمي كله لأعلى أو لأسفل معًا. وذلك التوحيد هو قوة السطوع وضعفه معًا: إنه أسرع طريقة لإصلاح صورة داكنة أو فاتحة عمومًا، لكنه لا يستطيع إصلاح صورة داكنة في جزء وفاتحة في آخر.</p>\n<p>فكر في السطوع كرفع أو خفض أضواء غرفة: كل شيء يضيء أو يظلم معًا، وتبقى الفروق النسبية بين الأجسام كما هي.</p>\n<h2 id=\"why-photos-are-dark\">لماذا تخرج الصور داكنة؟</h2>\n<p>كاميرات الهواتف غالبًا تقلل التعريض في ضوء معقد: سماء ساطعة خلف شخص أو نافذة في الخلفية أو مصدر ضوء قوي قد يخدع الكاميرا ويظلم الشخص.</p>\n<p>صور الداخل داكنة لسبب أبسط: لا يوجد ضوء كافٍ: غرفة مضاءة بمصباح واحد تعطي الكاميرا ضوءًا أقل بكثير من مشهد خارجي، والكاميرا تعوّض بسطوع أقل. ووثائق ممسوحة وصور قديمة غالبًا داكنة أيضًا: العمر يبهت المطبوعات، والماسحات تقرأ النغمات خطأ، والنتيجة صورة رمادية وضبابية تحتاج تفتيحًا.</p>\n<p>ولقطات الشاشة قد تكون داكنة عندما تكون الشاشة نفسها خافتة: صورة لشاشة أو لقطة ملتقطة بسطوع منخفض تحتاج دفعة لتصبح مقروءة.</p>\n<h2 id=\"brightening-vs-exposure\">التفتيح أم التعريض: هل هما نفس الشيء؟</h2>\n<p>السطوع والتعريض مرتبطان لكنهما ليسا متطابقين: التعريض يغيّر كم الضوء الذي التقطته الكاميرا، بينما السطوع يغيّر كيف تُعرض البكسلات الملتقطة.</p>\n<p>في محرر، يشعر الضابطان غالبًا بالتشابه، لأن كليهما يفتّح الصورة أو يظلمها: الفرق في كيفية معاملتهما أطراف النطاق النغمي. وتعديلات التعريض تميل إلى التأثير في الإضاءات والظلال بشكل مختلف، محافظة على تفاصيل أكثر في الحواف، بينما السطوع يحرك كل شيء بالتساوي، ما قد يغسل المناطق الفاتحة.</p>\n<p>ولإصلاح سريع في محرر متصفح، السطوع هو الأداة الصحيحة: بسيط ومتوقع وسريع، ولمعظم الصور يعطي النتيجة التي تريدها.</p>\n<h2 id=\"slider-explained\">منزلق السطوع موضح</h2>\n<p>يمتد منزلق السطوع من قيم سالبة إلى موجبة، والصفر يعني لا تغيير: تحريكه يمينًا يفتّح الصورة، وتحريكه يسارًا يظلمها.</p>\n<p>الحركات الصغيرة تحدث فرقًا كبيرًا: تغيير 10 إلى 15 بالمئة غالبًا يكفي لإصلاح صورة داكنة، والحركات الأكبر تغسل الإضاءات بسرعة. وتعرض الأداة صورتك بزيادة 15 بالمئة فور رفعها: نقطة البداية تلك تعطيك فكرة فورية عن شكل تفتيح معتدل.</p>\n<p>اسحب المنزلق ببطء وراقب المعاينة: التحديث المباشر يُظهر بالضبط كيف تستجيب الصورة، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة جيدة.</p>\n<h2 id=\"quick-presets\">إعدادات سريعة لإصلاحات بنقرة واحدة</h2>\n<p>تشمل الأداة إعدادات سريعة تطبق قيم سطوع شائعة بنقرة واحدة: طريقة سريعة لتجربة مستويات مختلفة دون سحب المنزلق.</p>\n<p>الإعدادات السريعة نقطة بداية لا إجابة نهائية: انقر واحدًا وراقب المعاينة ثم اضبط بالمنزلق إذا كانت النتيجة قريبة لكنها ليست صحيحة تمامًا. واستخدم الإعدادات السريعة لمقارنة خيارات بسرعة: إعداد 15 بالمئة بجانب إعداد 30 بالمئة يُظهر كم تفتيح تتحمل الصورة قبل أن تغتسل.</p>\n<p>ولدفعة صور متشابهة، نفس الإعداد السريع يحافظ على نتائج متسقة: مجموعة لقطات داخلية داكنة، كلها مفتّحة بنفس المقدار، تبدو كسلسلة.</p>\n<h2 id=\"compare-modes\">أوضاع المقارنة: قبل وبعد ومقسم</h2>\n<p>أوضاع المقارنة تُظهر الأصل والنسخة المعدلة معًا: عرض \"بعد\" يُظهر الصورة المفتّحة، وعرض \"قبل\" يُظهر الأصل، وعرض \"مقسم\" يُظهر الاثنتين جنبًا إلى جنب.</p>\n<p>المقارنة المقسمة هي الأنفع لعمل السطوع: تتيح لك رؤية أي المناطق تحسنت وأيها اغتسل بالضبط، بخط واضح بين النسختين. والمقارنة بملء الشاشة تعطي أكبر عرض: إنها أفضل طريقة للحكم على صورة مفتّحة، لأن الصورة بالحجم الكامل تُظهر تفاصيل تخفيها معاينة صغيرة.</p>\n<p>استخدم خيار \"الاحتفاظ لرؤية الأصل\" لمراجعة سريعة: استمر بالضغط لرؤية الأصل، وأفلت لرؤية التعديل، ويقفز الفرق إلى العين فورًا.</p>\n<h2 id=\"brightening-portraits\">كيف تفتّح صورًا شخصية</h2>\n<p>الصور الشخصية تحتاج تفتيحًا لطيفًا: وجه داكن جدًا يخفي العينين والتعبير، لكن وجهًا فاتحًا جدًا يفقد نسيج البشرة ويبدو مسطحًا.</p>\n<p>ابدأ بزيادة صغيرة 10 إلى 15 بالمئة وراجع نغمات البشرة: يجب أن يبدو الوجه مضاءً بشكل طبيعي، لا كأن فلاشًا أُطلق من قرب. وراقب الإضاءات في الجبهة والأنف: تلك المناطق تحترق أولًا، وصورة شخصية مفتّحة ببقع بيضاء على الوجه تبدو أسوأ من داكنة.</p>\n<p>ولصورة شخصية ملتقطة أمام نافذة ساطعة، قد لا يكفي التفتيح وحده: الوجه والخلفية يحتاجان معاملة مختلفة، وتعديل سطوع وحده يستطيع تحريك الاثنين معًا فقط.</p>\n<h2 id=\"brightening-landscapes\">كيف تفتّح مناظر طبيعية</h2>\n<p>المناظر غالبًا تحتاج تفتيحًا في الظلال بينما تبقى السماء فاتحة: زيادة سطوع موحدة قد تغسل السماء بينما تصلح المقدمة.</p>\n<p>استخدم زيادة معتدلة وراجع السماء أولًا: إذا فقدت الغيوم شكلها وتحولت إلى بياض فارغ، فقد تجاوزت الحد. ولمنظر بمقدمة داكنة وسماء فاتحة، فتّح بلطف واقبل بعض التسوية: الهدف صورة متوازنة لا مثالية.</p>\n<p>وصور الصباح والمساء هي الأكثر استفادة من التفتيح: الضوء المنخفض يعطي ألوانًا غنية، ودفعة صغيرة تُخرج التفاصيل دون قتل الجو.</p>\n<h2 id=\"brightening-screenshots\">كيف تفتّح لقطات شاشة ووثائق</h2>\n<p>لقطات الشاشة والوثائق الممسوحة تحتاج تفتيحًا أكثر عدوانية من الصور: يجب أن يكون النص مقروءًا، ومسح داكن بنص رمادي لا ينفع شيئًا.</p>\n<p>الصق لقطة مباشرة بـCtrl+V لتتخطى خطوة الحفظ: تظهر الصورة في المحرر فورًا، جاهزة للتفتيح. وزد السطوع حتى يصبح النص واضحًا وتصبح الخلفية بيضاء: وثيقة بخلفية بيضاء نظيفة ونص داكن سهلة القراءة والطباعة.</p>\n<p>وراقب الضجيج في المناطق الداكنة: لقطة مفتّحة كثيرًا قد تُظهر أنماط كتل خفيفة، خاصة في JPEG مضغوط أصلًا.</p>\n<h2 id=\"darkening-photos\">متى تظلم بدلًا من التفتيح</h2>\n<p>التظليم ينفع عندما تكون صورة مفرطة التعريض: صورة ساطعة ومغسولة بلا ظلال تحتاج سطوعًا سالبًا لاستعادة العمق والتباين.</p>\n<p>استخدم قيمًا سالبة مثل 15 أو 30 بالمئة سالبة لصورة فاتحة جدًا: تتعمق الظلال وتكتسب الألوان غنى ويشعر بالصورة أكثر صلابة. والتظليم يساعد أيضًا عندما توضع صورة خلف نص: صورة مظلمة تجعل النص الأبيض مقروءًا، ما ينفع في شرائح وملصقات ورسوم اجتماعية.</p>\n<p>ولصورة فاتحة جدًا في السماء وداكنة جدًا في المقدمة، لا اتجاه وحده يصلحها: اقبل تسوية أو استخدم تعديلًا آخر.</p>\n<h2 id=\"noise-and-quality\">الضجيج والجودة وحدود التفتيح</h2>\n<p>التفتيح يكشف الضجيج: صورة داكنة تخفي حبيباتها في الظلال، وعند رفع السطوع يظهر ذلك الحبيب كملمس منقّط.</p>\n<p>ضغط JPEG يزيد المشكلة سوءًا: JPEG داكن ومضغوط يُظهر أنماط كتل خفيفة عند تفتيحه كثيرًا، لأن مصنوعات الضغط تصبح مرئية. والحل أن تفتّح بلطف وتبدأ من أفضل أصل لديك: صورة ملتقطة بضوء جيد تحتاج تفتيحًا أقل، وتفتيح أقل يعني ضجيجًا أقل.</p>\n<p>والتفتيح لا يغيّر الأبعاد بالبكسلات ولا الدقة: تحتفظ الصورة بنفس الحجم، وتتغير النغمات فقط، فالتعديل نفسه لا يفقد تفاصيل.</p>\n<h2 id=\"formats-and-export\">الصيغ والتصدير</h2>\n<p>تقبل الأداة صيغ صور شائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 MB: وتستطيع التصدير كـJPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير كـPNG أو WebP يحافظ على شفافية الصورة الأساسية: إذا كان مصدرك رسم PNG شفافًا، فالتصدير المفتّح يحافظ على المناطق الشفافة سليمة. وللصور، JPG بضبط جودة عالية يعمل جيدًا: التفتيح لا يضيف كثيرًا إلى حجم الملف، فالتصدير يبقى قريبًا من الوزن الأصلي.</p>\n<p>ويظهر ضبط الجودة لتصديرات JPG وWebP، ويُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره.</p>\n<h2 id=\"brightness-and-contrast\">السطوع والتباين يعملان معًا</h2>\n<p>السطوع والتباين رفيقان: السطوع يحرك النطاق النغمي كله لأعلى أو لأسفل، بينما التباين يمد أو يضغط المسافة بين الطرفين الداكن والفاتح.</p>\n<p>صورة داكنة ومسطحة تحتاج التعديلين: فتّح أولًا لرفع المستوى العام، ثم أضف تباينًا لاستعادة العمق الذي غسله التفتيح. واستخدم <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> بعد التفتيح، عندما تبدو الصورة رمادية وبلا حياة: دفعة تباين صغيرة تعيد الظلال والإضاءات.</p>\n<p>ولمقارنة كاملة بين الضابطين، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">السطوع أم التعريض أم التباين: أساسيات التعديل</a>.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: تعديل دون رفع أي شيء</h2>\n<p>كل تعديل سطوع يحدث في متصفحك: صورك لا تُرفع أبدًا إلى خادم، وهو أمر مهم عندما تكون الصور شخصية أو صورًا عائلية أو عمل عملاء.</p>\n<p>هذه ميزة حقيقية مقابل محررات السحابة: صورة عائلية أو وثيقة خاصة لا يجب أن تسافر إلى خادم لا تستطيع رؤيته، فقط لتفتيحها. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة مفتّحة منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>احتفظ بالصورة الأصلية دون تعديل: بمجرد أن يُسطّح تغيير سطوع في تصدير، لا يمكن التراجع عنه من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند ضبط السطوع</h2>\n<p>أكثر خطأ شيوعًا التفتيح أكثر مما يلزم: صورة مدفوعة إلى 50 أو 100 بالمئة تفقد إضاءاتها تمامًا، والنتيجة صورة مسطحة وبيضاء بلا تفاصيل.</p>\n<p>خطأ آخر تفتيح صورة فاتحة أصلًا: صورة مفرطة التعريض تحتاج تظليمًا لا تفتيحًا، وإضافة مزيد من الضوء تزيدها سوءًا فقط. وينسى الناس أيضًا مراجعة الإضاءات: وجه أو سماء تبدو جيدة في معاينة صغيرة قد تكون محروقة بالحجم الكامل، فراجع النتيجة دائمًا بحجم كبير.</p>\n<p>وأخيرًا، لا تفتّح نفس JPG مرة بعد مرة: كل حفظ يضيف ضررًا، فعد دائمًا إلى الملف الأصلي عندما تريد مستوى سطوع مختلفًا.</p>\n<h2 id=\"brightness-workflow\">سير عمل لتعديلات سطوع نظيفة</h2>\n<p>ابدأ بالملف الأصلي وقرر كم تفتيح تحتاج: صورة داكنة قليلًا تحتاج 10 إلى 15 بالمئة، بينما داكنة جدًا قد تحتاج 30 بالمئة أو أكثر.</p>\n<p>طبّق السطوع ثم راجع عرض المقارنة: العرض المقسم يُظهر بالضبط أي المناطق تحسنت وأيها اغتسل. وأضف تباينًا إذا بدت الصورة مسطحة بعد التفتيح: دفعة تباين صغيرة تستعيد العمق الذي قد يغسله زيادة سطوع.</p>\n<p>صدّر بضبط جودة عالية وراجع النتيجة بالحجم الكامل: اقترب من المناطق الفاتحة وتأكد من عدم فقدان تفاصيل بسبب سطوع زائد.</p>\n<h2 id=\"brightening-for-social\">كيف تفتّح صورًا لوسائل التواصل الاجتماعي</h2>\n<p>خلاصات التواصل الاجتماعي تفضل صورًا فاتحة ومشرقة: صورة داكنة تُمرّر دون توقف، بينما صورة مضاءة جيدًا توقف الإبهام وتكسب نظرة ثانية.</p>\n<p>فتّح صور التواصل الاجتماعي أكثر قليلًا مما تفعل للطباعة: الشاشات تختلف في السطوع، وصورة تبدو جيدة على هاتفك قد تبدو داكنة على هاتف شخص آخر. وأبقِ التفتيح طبيعيًا: صورة مدفوعة بعيدًا جدًا تبدو مصطنعة، والمتابعون يلاحظون عندما لا يطابق الضوء المشهد.</p>\n<p>جرّب الصورة المفتّحة بحجم الخلاصة قبل النشر: صورة تبدو جيدة بالحجم الكامل قد تبدو داكنة جدًا أو فاتحة جدًا في معاينة صغيرة، فراجع قبل النشر.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-taadil-sutoo-as-sura/\">كيف تضبط سطوع صورة</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">السطوع أم التعريض أم التباين: أساسيات التعديل</a>، ولإصلاح التباين المسطح بعد التفتيح استخدم <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a>. وجرّب كل ضبط مجانًا في <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يجب أن أفتّح صورة داكنة؟","answer":"ابدأ بـ10 إلى 15 بالمئة وراجع المعاينة: معظم الصور الداكنة تحتاج دفعة صغيرة فقط، والحركات الأكبر تغسل الإضاءات بسرعة. وزد بخطوات صغيرة وتوقف عندما تبدو الصورة جيدة."},{"question":"لماذا تبدو صورتي مغسولة بعد تفتيحها؟","answer":"دُفع السطوع أكثر مما يلزم، ما يدفع الإضاءات إلى بياض نقي ويزيل كل تفاصيل المناطق الفاتحة. واخفض المنزلق حتى تُظهر السماء والبشرة والأسطح الفاتحة ملمسًا مجددًا. وإضافة تباين قليل تساعد أيضًا."},{"question":"هل يمكن للتفتيح إصلاح صورة ملتقطة بضوء قليل جدًا؟","answer":"جزئيًا: التفتيح يجعل صورة داكنة مرئية، لكنه يكشف أيضًا الضجيج ومصنوعات الضغط التي كانت مخفية في الظلال. ودفعة لطيفة من أصل جيد تعمل أفضل: صورة شبه سوداء لا تحمل تفاصيل كافية لاستعادتها."},{"question":"هل أفتّح صورة قبل قصها أم بعدها؟","answer":"فتّح بعد القص، لتحكم على السطوع على الإطار النهائي: القص أولًا يزيل أيضًا مناطق داكنة لا تحتاجها، ما قد يغيّر كم تفتيح تحتاجه المنطقة المحفوظة."},{"question":"هل تفتيح صورة يغيّر حجم ملفها؟","answer":"قليلًا فقط: التفتيح يغيّر قيم البكسلات لا عددها، فيبقى حجم الملف قريبًا من الأصل. وصيغة التصدير وضبط الجودة مهمان أكثر بكثير: JPG بجودة عالية يبقى خفيفًا، بينما PNG دون فقدان يكون أثقل."},{"question":"هل تفتيح صورة شخصية في أداة متصفح آمن؟","answer":"نعم، لأن كل المعالجة تحدث محليًا في متصفحك ولا يُرفع شيء إلى خادم. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير. واحتفظ بالملف الأصلي إذا أردت الحفاظ على بيانات الكاميرا."}];
